CREATE TABLE retail_posting(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,company_id bigint NOT NULL REFERENCES company(id),revision bigint NOT NULL DEFAULT 1,booked_on date NOT NULL,groups jsonb NOT NULL,cancelled boolean NOT NULL DEFAULT false,reason text NOT NULL,actor_id bigint NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id));
ALTER TABLE retail_document ADD COLUMN posting_id bigint,ADD FOREIGN KEY(company_id,posting_id) REFERENCES retail_posting(company_id,id);
ALTER TABLE cash_movement ADD COLUMN retail_posting_id bigint,ADD COLUMN retail_tax jsonb,ADD FOREIGN KEY(company_id,retail_posting_id) REFERENCES retail_posting(company_id,id);
CREATE TABLE retail_post_command(company_id bigint NOT NULL REFERENCES company(id),request_id uuid NOT NULL,actor_id bigint NOT NULL REFERENCES app_user(id),input jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,request_id));
